SELECT comment.id, user_id, media_id, user.username, comment FROM comment
LEFT JOIN user ON comment.user_id = user.id
WHERE media_id = #{id};

SELECT comment.id, user_id, media_id, user.username, comment FROM comment
LEFT JOIN user ON comment.user_id = user.id
WHERE media_id = #{mediaId} and user_id = #{userId};

SELECT person_id, person.name, role, character_name FROM media_person
LEFT JOIN person on media_person.person_id = person.id
WHERE media_person.media_id = #{id};
